function JT_Reference_chooseImage(){try{var f=File.openDialog('Choose a PNG reference image','PNG:*.png',false);if(!f)return JT_result(false,'No reference image selected.');if(!/\.png$/i.test(f.name))return JT_result(false,'Choose a PNG reference so its binary payload can be validated safely.');return JT_result(true,'Reference image selected.',{path:f.fsName,name:f.name})}catch(e){return JT_result(false,'Could not choose the reference image: '+e.message)}}
function JT_Approval_empty(){return{status:'in-review',reviewer:'',comments:[]}}
