function JT_Template_applyData(item,row,csvFolder,lockStatic){var t='',i,result,changed=false,m,key,value,file;try{t=item.typename;if(t==='TextFrame'){result=JT_Template_replaceText(item.contents,row);if(result.changed){item.contents=result.text;changed=true}}else if(t==='PlacedItem'){m=String(item.name||'').match(/\{\{image:([^}]+)\}\}/i);if(m){key=String(m[1]).replace(/^\s+|\s+$/g,'');value=JT_Template_value(row,key);if(value){file=new File(value);if(!file.exists&&csvFolder)file=new File(csvFolder.fsName+'/'+value);if(file.exists){item.file=file;changed=true}}}}else if(t==='GroupItem'){for(i=0;i<item.pageItems.length;i++)if(JT_Template_applyData(item.pageItems[i],row,csvFolder,lockStatic))changed=true}else if(t==='CompoundPathItem'){for(i=0;i<item.pathItems.length;i++)if(JT_Template_applyData(item.pathItems[i],row,csvFolder,lockStatic))changed=true}if(lockStatic&&!changed&&t!=='GroupItem'&&t!=='CompoundPathItem')item.locked=true}catch(ignore){}return changed}
function JT_Template_generate(templateIndex,rowsJSON,lockStatic,csvPath){try{var d=JT_doc();if(!d)return JT_result(false,'No Illustrator document is open.');templateIndex=Math.round(Number(templateIndex));if(templateIndex<0||templateIndex>=d.artboards.length)return JT_result(false,'Choose a valid document template.');var rows=JT_parseJSON(rowsJSON,[]);if(!(rows instanceof Array)||!rows.length)return JT_result(false,'The CSV contains no usable data rows.');if(rows.length>250)rows=rows.slice(0,250);var b=d.artboards[templateIndex].artboardRect,w=b[2]-b[0],h=b[1]-b[3],items=JT_DP_collect(d,b);if(!items.length)return JT_result(false,'The selected template artboard has no supported artwork.');var layer=JT_uniqueLayer(d,'Jaiafa Batch Output'),csvFolder=csvPath?new File(csvPath).parent:null,count=0,lastIndex=templateIndex,r,left,top,ab,g,dx,dy,i,j,dup,rowName;for(r=0;r<rows.length;r++){left=JT_rightmost(d)+90;top=b[1];rowName=JT_Template_value(rows[r],'name')||JT_Template_value(rows[r],'title')||('Row '+(r+1));ab=d.artboards.add([left,top,left+w,top-h]);ab.name=JT_uniqueArtboardName(d,'Batch — '+JT_safeName(rowName));lastIndex=d.artboards.length-1;g=layer.groupItems.add();g.name=ab.name+' Artwork';dx=left-b[0];dy=top-b[1];for(i=0;i<items.length;i++){try{dup=items[i].duplicate(g,ElementPlacement.PLACEATEND);dup.translate(dx,dy);JT_Template_applyData(dup,rows[r],csvFolder,lockStatic===true)}catch(ignore0){}}count++}d.artboards.setActiveArtboardIndex(lastIndex);redraw();return JT_result(true,count+' data-driven artboard'+(count===1?' generated.':'s generated.'),{count:count,artboardIndex:lastIndex})}catch(e){return JT_result(false,'Batch generation failed: '+e.message)}}
function JT_Production_scanFixed(brandJSON,minStroke){var raw=JT_Production_scan(brandJSON,minStroke),r=JT_parseJSON(raw,null);if(!r||!r.success)return raw;return JT_result(true,'Production preflight completed · '+Number(r.linkedCount||0)+' linked · '+Number(r.embeddedCount||0)+' embedded asset'+(Number(r.embeddedCount||0)===1?'.':'s.'),{findings:r.findings||'[]',score:Number(r.score)||0,count:Number(r.count)||0,linkedCount:Number(r.linkedCount)||0,embeddedCount:Number(r.embeddedCount)||0})}
function JT_QA_prepareFixesSafe(brandJSON,safeMargin){var raw=JT_QA_prepareFixes(brandJSON,safeMargin),r=JT_parseJSON(raw,null);if(!r||!r.success)return raw;var fixes=JT_parseJSON(r.fixes,[]),map=JT_DP_cacheMap(),safe=Math.max(0,Number(safeMargin)||0),b=JT_DP_SOURCE_BOUNDS,innerW=b?(b[2]-b[0]-safe*2):0,innerH=b?(b[1]-b[3]-safe*2):0,out=[],i,ops,item,gb;for(i=0;i<fixes.length;i++){ops=JT_DP_parsePayload(fixes[i].row);if(ops.length&&ops[0][1]==='move'){item=map[ops[0][0]];try{gb=item.geometricBounds;if((gb[2]-gb[0])>innerW||(gb[1]-gb[3])>innerH)continue}catch(ignore){continue}}out.push(fixes[i])}return JT_result(true,out.length?out.length+' safe QA fix'+(out.length===1?' prepared.':'es prepared.'):'No deterministic QA fixes are needed.',{fixes:JSON.stringify(out),count:out.length})}
function JT_Production_scanFixed(brandJSON,minStroke){try{var d=JT_doc();if(!d)return JT_result(false,'No Illustrator document is open.');minStroke=Math.max(0,Number(minStroke)||.25);var findings=[],stats={thin:0,overprint:0,spot:0,richBlack:0},i,j,item,file,missing=0,linked=0,embedded=d.rasterItems.length,lowRes=0,rgbRaster=0,missingFonts=0,fonts={},fontCount=0,layer;for(i=0;i<d.layers.length;i++){layer=d.layers[i];if(layer.name===JT_HISTORY_LAYER||layer.name===JT_APPROVAL_DATA_LAYER)continue;for(j=0;j<layer.pageItems.length;j++){item=layer.pageItems[j];try{if(item.parent===layer)JT_Production_item(item,stats,minStroke)}catch(ignore0){}}}for(i=0;i<d.placedItems.length;i++){item=d.placedItems[i];try{file=item.file;if(file&&file.exists)linked++;else missing++}catch(ignore1){missing++}}for(i=0;i<d.rasterItems.length;i++){item=d.rasterItems[i];try{if(typeof item.resolution!=='undefined'&&Number(item.resolution)>0&&Number(item.resolution)<150)lowRes++}catch(ignore2){}try{if(String(item.imageColorSpace).toLowerCase().indexOf('rgb')>=0&&String(d.documentColorSpace).toLowerCase().indexOf('cmyk')>=0)rgbRaster++}catch(ignore3){}}for(i=0;i<d.textFrames.length;i++){try{var font=d.textFrames[i].textRange.characterAttributes.textFont;if(font)fonts[font.name]=true;else missingFonts++}catch(ignore4){missingFonts++}}for(var key in fonts)if(!fonts.hasOwnProperty||fonts.hasOwnProperty(key))fontCount++;if(missing)JT_QA_add(findings,'Assets','Missing linked files',missing+' placed asset'+(missing===1?' cannot':'s cannot')+' be found at the stored file path.','high');if(missingFonts)JT_QA_add(findings,'Fonts','Missing or substituted fonts',missingFonts+' text frame'+(missingFonts===1?' has':'s have')+' an unavailable font reference.','high');if(lowRes)JT_QA_add(findings,'Assets','Low-resolution raster images',lowRes+' embedded raster image'+(lowRes===1?' reports':'s report')+' less than 150 PPI.','high');if(rgbRaster)JT_QA_add(findings,'Color','RGB images in a CMYK document',rgbRaster+' raster image'+(rgbRaster===1?' is':'s are')+' RGB while the document is CMYK.','medium');if(stats.thin)JT_QA_add(findings,'Production','Strokes below minimum',stats.thin+' stroked path'+(stats.thin===1?' is':'s are')+' thinner than '+minStroke+' pt.','medium');if(stats.richBlack)JT_QA_add(findings,'Production','Rich-black objects',stats.richBlack+' object'+(stats.richBlack===1?' uses':'s use')+' K plus CMY. Confirm this is intentional, especially for small type.','medium');if(stats.spot)JT_QA_add(findings,'Production','Spot colors present',stats.spot+' object'+(stats.spot===1?' uses':'s use')+' a spot color. Confirm separations and naming.','low');if(stats.overprint)JT_QA_add(findings,'Production','Overprint enabled',stats.overprint+' path'+(stats.overprint===1?' has':'s have')+' fill or stroke overprint enabled.','low');var score=100;for(i=0;i<findings.length;i++)score-=findings[i].severity==='high'?18:(findings[i].severity==='medium'?9:4);if(score<0)score=0;return JT_result(true,'Production preflight completed · '+linked+' linked · '+embedded+' embedded · '+fontCount+' font'+(fontCount===1?'.':'s.'),{findings:JSON.stringify(findings),score:score,count:findings.length,linkedCount:linked,embeddedCount:embedded,fontCount:fontCount})}catch(e){return JT_result(false,'Production preflight failed: '+e.message)}}
